<?php /** 출퇴근 시스템 사이드바 위젯 */ use App\Core\Db; require_once __DIR__.'/../attendance/common.php'; $pdo=Db::pdo(); $eid=attendance_employee_id($pdo); $today=attendance_today(); $status='출근 전';$in='-';$out='-'; if($pdo&&$eid>0){ try{$st=$pdo->prepare("SELECT * FROM cpms_attendance_records WHERE employee_id=:e AND work_date=:d LIMIT 1");$st->execute(array(':e'=>$eid,':d'=>$today));$r=$st->fetch(); if($r){$status=$r['status'];$in=$r['check_in']?$r['check_in']:'-';$out=$r['check_out']?$r['check_out']:'-';} $lv=$pdo->prepare("SELECT leave_type FROM cpms_leave_records WHERE employee_id=:e AND leave_date=:d LIMIT 1");$lv->execute(array(':e'=>$eid,':d'=>$today));$l=$lv->fetchColumn(); if($l)$status=$l; }catch(Exception $e){} }
?>
<div class="mt-3 text-xs text-gray-600"><!-- 사이드바 출퇴근 UI 정리 -->현재 상태: <b><?php echo h($status);?></b><br>출근: <?php echo h($in);?> / 퇴근: <?php echo h($out);?></div>
<form method="post" action="?r=attendance/check_in" class="mt-2"><input type="hidden" name="_csrf" value="<?php echo h(csrf_token());?>"><button class="px-2 py-1 bg-blue-600 text-white rounded">출근</button></form>
<form method="post" action="?r=attendance/check_out" class="mt-1"><input type="hidden" name="_csrf" value="<?php echo h(csrf_token());?>"><button class="px-2 py-1 bg-emerald-600 text-white rounded">퇴근</button></form>